function escapeHtml(s){ return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'); }
function unescapeHtml(s){ return String(s).replace(/&quot;/g,'"').replace(/&gt;/g,'>').replace(/&lt;/g,'<').replace(/&amp;/g,'&'); }
function minifyHtml(html){
  return String(html)
    .replace(/<!--[\s\S]*?-->/g,'')
    .replace(/\s+</g,'<')
    .replace(/>\s+/g,'>')
    .replace(/\n\s*/g,'')
    .trim();
}
function nl(d){ var s='\n'; for(var i=0;i<d;i++) s+='  '; return s; }
function formatHtml(html){
  html=String(html).replace(/<!--[\s\S]*?-->/g,'');
  var out=''; var depth=0; var re=/<[^>]+>|[^<]+/g; var m;
  while((m=re.exec(html))){
    var tok=m[0];
    if(tok[0]==='<'){
      if(tok[1]==='/'){ depth=Math.max(0,depth-1); out+=nl(depth)+tok; }
      else if(tok[tok.length-2]==='/'){ out+=nl(depth)+tok; }
      else { out+=nl(depth)+tok; depth++; }
    } else {
      var v=tok.replace(/\s+/g,' ').trim(); if(v) out+=nl(depth)+v;
    }
  }
  return out.replace(/^\n+/,'');
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { minifyHtml:minifyHtml, formatHtml:formatHtml, escapeHtml:escapeHtml, unescapeHtml:unescapeHtml };
}
if (typeof window !== 'undefined') {
  window.HtmlForgePure = { minifyHtml:minifyHtml, formatHtml:formatHtml, escapeHtml:escapeHtml, unescapeHtml:unescapeHtml };
}
